"""Independent prior Fraction-derived expectations applied to installed P6 numbers, never regenerated by SUT."""
from pathlib import Path
import json,hashlib,sys
from decimal import localcontext
from aqrp.ui import numbers
O=Path(__file__).parent;prior=O.parent/'p6-g1-recheck-e71f6f0-independent'
extension=json.loads((prior/'NUMERIC_EXTENSION_INPUTS.json').read_bytes())['records']
answers=json.loads((prior/'INDEPENDENT_127_ANSWERS.json').read_bytes())['records']
valid_kinds={'weight','money','ic_display','percent_display','small','quantity'}
cases=[dict(kind=c['kind'],inputs=c['inputs'],independent=c['independent'],error=None) for c in answers if c['kind'] in valid_kinds]+extension
# This module exposes decimal parsing/formatting, not a quantity-domain validator.
# The input examples here are valid integer quantities; quantity-specific rejection stays at core schema.
def candidate(c):
 k=c['kind'];x=c['inputs']
 if k=='weight':return numbers.percent(x['percent'])
 if k=='money':return numbers.fixed_view(x['value'],2,grouping=True)
 if k=='ic_display':return numbers.fixed_view(x['value'],4)
 if k=='percent_display':return numbers.fixed_view(x['value'],4,multiply=100)+'%'
 return numbers.exact_text(*numbers.decimal_parts(x['value']))
records=[]
for prec,traps in [(2,False),(9,True),(28,False),(28,True),(60,True),(4300,True)]:
 with localcontext() as ctx:
  ctx.prec=prec
  for signal in ctx.traps:ctx.traps[signal]=traps
  for i,c in enumerate(cases):
   try:actual=candidate(c);error=None
   except numbers.ReferenceNumberError as exc:actual=None;error=exc.code
   passed=type(actual) is type(c['independent']) and actual==c['independent'] and error==c['error']
   records.append(dict(case_index=i,precision=prec,all_traps=traps,passed=passed,actual_sha256=hashlib.sha256(str(actual).encode()).hexdigest(),error=error))
assert len(cases)==852 and len(records)==5112 and all(r['passed'] for r in records)
out=dict(executor='GPT Work supplemental reviewer',scope='Actual installed numbers module; exact expectations previously independently computed using Fraction/round, not from SUT',python=sys.executable,module=str(Path(numbers.__file__)),module_sha256=hashlib.sha256(Path(numbers.__file__).read_bytes()).hexdigest(),input_bindings=[dict(path=str(prior/n),sha256=hashlib.sha256((prior/n).read_bytes()).hexdigest()) for n in ['NUMERIC_EXTENSION_INPUTS.json','INDEPENDENT_127_ANSWERS.json']],input_cases=852,observations=5112,passed=5112,records=records)
(O/'INSTALLED_NUMERIC_RESULTS.json').write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8')
print(json.dumps(dict(cases=852,observations=5112,passed=5112,module=out['module'])))

